{
  "title": "The Bridge Out of the Broken Crown",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The team studies a map of the ruined royal city.",
      "visual_description": "Four figures huddle on a moss-covered hill at dusk, an unrolled parchment map weighted down with stones; the silhouette of a shattered castle skyline rises behind them.",
      "characters": ["map_reader", "scout", "magic_helper", "bridge_walker"]
    },
    {
      "scene_number": 2,
      "caption": "The scout spots the castle gates from a ridge.",
      "visual_description": "The scout crouches behind a broken statue, brass spyglass raised toward enormous iron gates flanked by cracked lion carvings.",
      "characters": ["scout"]
    },
    {
      "scene_number": 3,
      "caption": "A frightened townsperson warns them away.",
      "visual_description": "A hooded townsperson clutches a lantern at a leaning doorway in a narrow ruined alley, gesturing nervously toward the inner city.",
      "characters": ["map_reader", "townsperson"]
    },
    {
      "scene_number": 4,
      "caption": "The map reader marks a hidden route through the rubble.",
      "visual_description": "Close-up of gloved hands inking a red line across the map beside a tipped-over well, with rubble and weeds in the background.",
      "characters": ["map_reader", "scout"]
    },
    {
      "scene_number": 5,
      "caption": "Armored patrols march past the broken fountain.",
      "visual_description": "Three armored patrol soldiers in tarnished plate stride through a plaza of dry, cracked fountain basins; the team hides in shadow behind a tilted column.",
      "characters": ["scout", "magic_helper", "patrol_soldier"]
    },
    {
      "scene_number": 6,
      "caption": "Old royal banners flutter above empty barracks.",
      "visual_description": "Tattered crimson banners with a faded crown sigil snap in the wind over a deserted courtyard; the bridge_walker pauses to look up at them.",
      "characters": ["bridge_walker", "map_reader"]
    },
    {
      "scene_number": 7,
      "caption": "Rumors of a dragon stop them in the market ruins.",
      "visual_description": "A trembling market vendor points at deep scorch marks scoring the cobblestones, the team listening with wide eyes amid overturned stalls.",
      "characters": ["market_vendor", "scout", "magic_helper"]
    },
    {
      "scene_number": 8,
      "caption": "The cursed tower looms over a poisoned garden.",
      "visual_description": "A leaning black tower wrapped in violet thorny vines, sickly purple mist drifting between dead rose bushes; the team approaches cautiously down a stone path.",
      "characters": ["map_reader", "magic_helper", "bridge_walker", "scout"]
    },
    {
      "scene_number": 9,
      "caption": "The magic helper reads the tower's warning runes.",
      "visual_description": "Glowing blue runes spiral across the tower's iron door; the magic_helper traces them with a slender wand, sparks reflecting in their eyes.",
      "characters": ["magic_helper"]
    },
    {
      "scene_number": 10,
      "caption": "A sleepy gate official blocks the inner courtyard.",
      "visual_description": "A round, half-asleep official in a too-big tabard slumps on a stool in front of an arched gate, keys dangling from one hand, snoring lightly.",
      "characters": ["sleepy_official", "map_reader", "scout"]
    },
    {
      "scene_number": 11,
      "caption": "The team bluffs past the sleepy official.",
      "visual_description": "The map_reader bows theatrically with a forged seal while the others tiptoe behind; the official squints with one bleary eye.",
      "characters": ["map_reader", "sleepy_official", "magic_helper", "bridge_walker", "scout"]
    },
    {
      "scene_number": 12,
      "caption": "A magic door bars the throne room.",
      "visual_description": "An enormous double door of pale stone covered in rotating concentric rings of glyphs glows softly in a dim hall lit by hovering candles.",
      "characters": ["magic_helper", "map_reader"]
    },
    {
      "scene_number": 13,
      "caption": "The magic helper unlocks the door with a riddle.",
      "visual_description": "The magic_helper holds up a glowing crystal; the glyph rings click into alignment, casting prismatic light across the team's faces.",
      "characters": ["magic_helper", "scout", "bridge_walker", "map_reader"]
    },
    {
      "scene_number": 14,
      "caption": "They find the captive bound beneath the throne.",
      "visual_description": "A young captive in tattered fine robes is chained to the base of a cracked obsidian throne; dust motes drift in a single shaft of light from a broken ceiling.",
      "characters": ["captive", "map_reader", "magic_helper"]
    },
    {
      "scene_number": 15,
      "caption": "Patrols rush the corridor as the team flees.",
      "visual_description": "Armored patrol soldiers charge down a long stone corridor, halberds lowered; the team sprints toward us with the captive between them.",
      "characters": ["patrol_soldier", "scout", "bridge_walker", "captive", "magic_helper", "map_reader"]
    },
    {
      "scene_number": 16,
      "caption": "A dragon's shadow sweeps across the rooftops.",
      "visual_description": "Massive winged shadow blots out the moon above sloped tile roofs; the team ducks behind a chimney, faces lit red by distant fire.",
      "characters": ["scout", "captive", "bridge_walker", "magic_helper", "map_reader"]
    },
    {
      "scene_number": 17,
      "caption": "The bridge walker steadies the collapsing bridge.",
      "visual_description": "A long stone bridge fractures over a deep ravine; the bridge_walker stands at its center, arms outstretched, golden light pouring from their feet into the cracks.",
      "characters": ["bridge_walker", "captive", "scout", "map_reader", "magic_helper"]
    },
    {
      "scene_number": 18,
      "caption": "The team escapes across the bridge at dawn.",
      "visual_description": "Silhouettes of five figures crossing a glowing stone bridge as pink dawn breaks over the distant ruins of the royal city behind them.",
      "characters": ["map_reader", "scout", "magic_helper", "bridge_walker", "captive"]
    }
  ]
}

